  // Plant Proteins
  'faba bean protein': { risk: IngredientRisk.Low, category: 'proteins', explanation: 'Isolated protein from fava beans (Vicia faba); emerging plant protein alternative — complete amino acid profile, naturally gluten-free, allergen profile still being characterized (not a top-9 allergen).' },
