  // Functional & Specialty Additives
  'chicory root inulin': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Prebiotic fructooligosaccharide fiber from chicory root; feeds beneficial Bifidobacterium — FDA recognizes it as dietary fiber on Nutrition Facts labels. May cause gas and bloating at doses >10g/day in sensitive individuals.' },
  'isomalto-oligosaccharides (vegetable source)': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Prebiotic soluble fiber from plant starch; FDA dietary fiber classification — significantly less fermentable than inulin, lower likelihood of digestive discomfort.' },
  'isomalto-oligosaccharide': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Plant-derived prebiotic oligosaccharide; used as a low-glycemic bulking agent and fiber supplement — FDA dietary fiber, generally well-tolerated.' },
  'jerusalem artichoke inulin': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Prebiotic fructooligosaccharide fiber from Helianthus tuberosus; higher short-chain fructooligosaccharide content than chicory inulin — very effective prebiotic but may cause significant gas in sensitive individuals.' },
  'cassava root fiber': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Soluble dietary fiber from cassava (tapioca root); used as a low-FODMAP prebiotic fiber — FDA dietary fiber classification, generally well-tolerated even by those sensitive to inulin.' },
  'psyllium': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Soluble fiber from Plantago ovata husks; FDA-approved health claim for reducing LDL cholesterol and heart disease risk — forms a gel in water that slows digestion and lowers glycemic response.' },
  'soluble corn fiber': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Partially hydrolyzed corn starch fiber; FDA-recognized dietary fiber — lower fermentability than inulin with good digestive tolerance, used as a prebiotic and bulking agent.' },
  'sugarcane fiber': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Insoluble fiber from sugarcane bagasse; primarily cellulose — FDA dietary fiber, used to boost fiber content in processed foods with minimal flavor impact.' },
  'organic tapioca fiber': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Certified organic soluble fiber from cassava/tapioca starch; similar to cassava root fiber — FDA dietary fiber, well-tolerated prebiotic with low fermentability.' },
  'organic agave inulin': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Certified organic prebiotic fiber from agave (not to be confused with agave syrup); a short-chain fructooligosaccharide — FDA dietary fiber, effective prebiotic for Bifidobacterium growth.' },
  'datem': { risk: IngredientRisk.Medium, category: 'emulsifiers', explanation: 'Diacetyl tartaric acid ester of mono- and diglycerides (E472e); a dough strengthener and emulsifier — FDA GRAS, but may be derived from animal fats (not always vegan) and is a highly processed additive.' },
  'modified corn starch': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Corn starch chemically or physically treated to alter its thickening and stability properties; FDA GRAS — modifications may include phosphorylation, acetylation, or hydroxypropylation. Medium concern for processed nature and high glycemic index.' },
  'modified tapioca starch': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Cassava starch treated to improve texture stability (freeze-thaw, heat resistance); FDA GRAS — same modification concerns as modified corn starch. Often labeled as a "clean label" alternative though still chemically modified.' },
  'modified resistant tapioca starch': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Tapioca starch modified to resist digestion; classified as a dietary fiber — resists small intestinal digestion, fermented by beneficial gut bacteria, lower glycemic impact than regular starch.' },
  'native corn starch': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Unmodified corn starch as it naturally occurs; FDA GRAS thickener — rapidly digested with high glycemic index, but no chemical modifications.' },
  'native cornstarch': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Unmodified corn starch; same as native corn starch — FDA GRAS, no chemical treatment, high glycemic index.' },
  'rice starch': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Fine starch granules extracted from rice; naturally gluten-free thickener — FDA GRAS, hypoallergenic with good digestibility, used in infant formula and gluten-free products.' },
  'modified cellulose': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Chemically modified plant cellulose (methylcellulose or carboxymethylcellulose); FDA GRAS — passes through the GI tract without digestion, used as a fiber source and texture modifier.' },
