  'dextrin': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Partially hydrolyzed starch; medium glycemic impact as it\'s more digestible than intact starch — FDA GRAS, used as a soluble fiber source in some contexts but primarily as a binding agent.' },
  'calcium propionate': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Calcium salt of propionic acid; a common mold inhibitor in bread — FDA GRAS (21 CFR 184.1221), some studies link daily consumption to irritability and sleep disruption in children at high doses.' },
  'calcium propionate (a preservative)': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Calcium propionate used as a bread preservative; FDA GRAS — effective mold prevention, considered safe at food-use levels though some sensitivity in children reported.' },
