  'calcium propionate (to preserve freshness)': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Calcium propionate bread preservative; FDA GRAS (21 CFR 184.1221) — commonly used in commercial bread to extend shelf life by inhibiting mold growth.' },
  'calcium disodium edta (to protect flavor)': { risk: IngredientRisk.Medium, category: 'preservatives', explanation: 'Calcium disodium EDTA (ethylenediaminetetraacetic acid); chelating agent that prevents metal-catalyzed oxidation — FDA GRAS but synthetic chelator that can bind and deplete trace minerals in the GI tract at high intake.' },
  'calcium disodium edta (used to protect quality)': { risk: IngredientRisk.Medium, category: 'preservatives', explanation: 'Calcium disodium EDTA antioxidant preservative; FDA GRAS at limited levels — chelating action preserves color and flavor but may reduce absorption of minerals like iron, zinc, and calcium.' },
  'sorbic acid': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Naturally occurring fatty acid from mountain ash berries used as a mold and yeast inhibitor; FDA GRAS (21 CFR 182.3089) — widely considered safe, one of the most natural-sourced preservatives.' },
