  'cultured dextrose': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Fermentation of glucose by Propionibacterium creating propionic acid naturally; used as a "clean label" preservative alternative to calcium propionate — FDA GRAS, same antimold mechanism as chemical preservatives but from fermentation.' },
  'cultured celery powder': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Dried celery juice fermented to convert naturally occurring nitrates to nitrites; used in "no nitrite added" cured meats — functionally equivalent to sodium nitrite (the celery-derived nitrites behave identically), sometimes considered misleading labeling.' },
