  'guarana (paullinia cupana) seed extract': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Caffeine-rich seed extract from South American Paullinia cupana; ~2× the caffeine concentration of coffee by weight — same dose-dependent stimulant effects as other caffeine sources.' },
  'guarana seed extract': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Concentrated guarana seed caffeine extract; same physiological caffeine effects at equivalent doses — FDA GRAS, medium concern for caffeine content especially in combination with other caffeine sources.' },
  'taurine': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Conditionally essential amino acid sulfonic acid; naturally produced by the body and found in meat and fish — FDA GRAS, extensively studied in energy drinks at 1-3g doses with no established adverse effects.' },
  'l-carnitine l-tartrate': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Carnitine amino acid in tartrate salt form; FDA GRAS — supports fatty acid transport into mitochondria. At supplement doses >2g/day, gut bacteria convert it to TMAO, a cardiovascular risk marker — food-use levels are lower.' },
  'd-glucuronolactone': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Glucose metabolite used in energy drinks; FDA GRAS at food-use levels — limited independent human safety data compared to caffeine and taurine; medium concern for novel ingredient with limited long-term study.' },
